package dev.kubejseditor.recipe.compat;

import com.google.gson.*;
import java.util.*;

/** JSON pointers are independent of Minecraft and never traverse component payloads implicitly. */
public final class CompatJson {
    public static String escape(String key){return key.replace("~","~0").replace("/","~1");}
    public static List<String> parts(String pointer){if(pointer==null||!pointer.startsWith("/"))throw new IllegalArgumentException("字段路径必须以 / 开头");return Arrays.stream(pointer.substring(1).split("/",-1)).map(s->s.replace("~1","/").replace("~0","~")).toList();}
    public static JsonElement get(JsonElement root,String path){try{JsonElement value=root;for(String key:parts(path)){if(value==null)return JsonNull.INSTANCE;value=value.isJsonArray()?value.getAsJsonArray().get(Integer.parseInt(key)):value.getAsJsonObject().get(key);}return value==null?JsonNull.INSTANCE:value;}catch(RuntimeException e){return JsonNull.INSTANCE;}}
    public static void set(JsonObject root,String path,JsonElement value){var keys=parts(path);JsonElement owner=root;for(int i=0;i<keys.size()-1;i++){String key=keys.get(i);if(owner.isJsonArray())owner=owner.getAsJsonArray().get(Integer.parseInt(key));else{var o=owner.getAsJsonObject();if(!o.has(key)||o.get(key).isJsonNull())o.add(key,new JsonObject());owner=o.get(key);}}String key=keys.getLast();if(owner.isJsonArray())owner.getAsJsonArray().set(Integer.parseInt(key),value.deepCopy());else owner.getAsJsonObject().add(key,value.deepCopy());}
    public static void remove(JsonObject root,String path){var keys=parts(path);JsonElement owner=root;for(int i=0;i<keys.size()-1;i++)owner=owner.isJsonArray()?owner.getAsJsonArray().get(Integer.parseInt(keys.get(i))):owner.getAsJsonObject().get(keys.get(i));if(owner.isJsonArray())owner.getAsJsonArray().remove(Integer.parseInt(keys.getLast()));else owner.getAsJsonObject().remove(keys.getLast());}
    public static String shape(JsonElement value){if(value==null||value.isJsonNull())return "null";if(value.isJsonArray()){var a=value.getAsJsonArray();return "["+a.size()+":"+a.asList().stream().map(CompatJson::shape).toList()+"]";}if(value.isJsonObject()){var o=value.getAsJsonObject();return new TreeSet<>(o.keySet()).stream().filter(k->!k.equals("components")).map(k->k+":"+(k.equals("type")?o.get(k):shape(o.get(k)))).toList().toString();}var p=value.getAsJsonPrimitive();return p.isBoolean()?"boolean":p.isNumber()?"number":"string";}
    public static boolean equal(JsonElement a,JsonElement b){if(a==null||b==null)return a==b;if(a.isJsonPrimitive()&&b.isJsonPrimitive()&&a.getAsJsonPrimitive().isNumber()&&b.getAsJsonPrimitive().isNumber())return a.getAsBigDecimal().compareTo(b.getAsBigDecimal())==0;if(a.isJsonArray()&&b.isJsonArray()){if(a.getAsJsonArray().size()!=b.getAsJsonArray().size())return false;for(int i=0;i<a.getAsJsonArray().size();i++)if(!equal(a.getAsJsonArray().get(i),b.getAsJsonArray().get(i)))return false;return true;}if(a.isJsonObject()&&b.isJsonObject()){if(!a.getAsJsonObject().keySet().equals(b.getAsJsonObject().keySet()))return false;for(String k:a.getAsJsonObject().keySet())if(!equal(a.getAsJsonObject().get(k),b.getAsJsonObject().get(k)))return false;return true;}return a.equals(b);}
    public static JsonElement canonical(JsonElement value){if(value.isJsonObject()){var out=new JsonObject();for(String key:new TreeSet<>(value.getAsJsonObject().keySet()))out.add(key,canonical(value.getAsJsonObject().get(key)));return out;}if(value.isJsonArray()){var out=new JsonArray();for(var entry:value.getAsJsonArray())out.add(canonical(entry));return out;}return value.deepCopy();}
    /** Data mappings can serve different list lengths; visual markings deliberately cannot. */
    public static String mappingShape(JsonElement value){if(value!=null&&value.isJsonArray())return new TreeSet<>(value.getAsJsonArray().asList().stream().map(CompatJson::mappingShape).toList()).toString();if(value!=null&&value.isJsonObject()){var o=value.getAsJsonObject();return new TreeSet<>(o.keySet()).stream().filter(k->!k.equals("components")).map(k->k+":"+(k.equals("type")?o.get(k):mappingShape(o.get(k)))).toList().toString();}return shape(value);}
    private CompatJson(){}
}
